\":\"current\",\"linkmenu\":\"101\",\"linkurl\":\"\",\"linkarticle\":\"\",\"url_type\":\"1\",\"urlbannertext\":\"\",\"linktarget\":\"\",\"bannertitle_status\":\"1\",\"bannertitle\":\"\",\"bannerdesc\":\"\",\"banner_alt\":\"\",\"banner_caption\":\"\",\"image_full\":\"\",\"image_big\":\"\",\"image_screen\":\"\",\"image_medium\":\"\",\"image_small\":\"\",\"image_tiny\":\"\"}', '{\"image_full\":\"\",\"image_big\":\"\",\"image_screen\":\"\",\"image_medium\":\"\",\"image_small\":\"\",\"image_tiny\":\"\"}', '{\"image_full\":\"\",\"image_big\":\"\",\"image_screen\":\"\",\"image_medium\":\"\",\"image_small\":\"\",\"image_tiny\":\"\"}', 0, 0, '', '', '', '', '{\"0\":{\"urltext\":\"\",\"video_status\":\"1\",\"url\":\"https:\\/\\/www.youtube.com\\/embed\\/DQh3B14bZnI\",\"video_title\":\"\",\"video_alt\":\"\",\"video_caption\":\"\",\"description\":\"\",\"images\":{\"image_full\":\"\",\"image_big\":\"\",\"image_screen\":\"\",\"image_medium\":\"\",\"image_small\":\"\",\"image_tiny\":\"\"}}}', '16by9', 'allowfullscreen', '{\"link_type\":\"\",\"link_menu\":\"101\",\"link_url\":\"\",\"link_article\":\"\",\"link_target\":\"\",\"link_rel\":\"\"}', '{\"urla\":false,\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":false,\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":false,\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_icons\":\"\",\"show_print_icon\":\"\",\"show_email_icon\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show