-- --------------------------------------------------------

--
-- Table structure for table `dpjvy_standard_extras`
--

CREATE TABLE `dpjvy_standard_extras` (
  `id` int(1) UNSIGNED NOT NULL,
  `vendor_id` int(10) UNSIGNED NOT NULL DEFAULT 1,
  `tax_id` int(10) NOT NULL DEFAULT 0,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'Name of the extra method',
  `alias` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `introtext` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `fulltext` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `currency_id` int(10) UNSIGNED DEFAULT NULL,
  `price` decimal(15,5) NOT NULL DEFAULT 0.00000 COMMENT 'Extra Cost',
  `nbproducts_start` int(10) UNSIGNED NOT NULL COMMENT 'Minimum number of products',
  `nbproducts_stop` int(10) UNSIGNED NOT NULL COMMENT 'Maximum number of products',
  `orderamount_start` decimal(15,5) NOT NULL DEFAULT 0.00000 COMMENT 'Minimum order amount',
  `orderamount_stop` decimal(15,5) NOT NULL DEFAULT 0.00000 COMMENT 'Maximum order amount',
  `package_fee` decimal(15,5) NOT NULL DEFAULT 0.00000 COMMENT 'Package Fee',
  `free_extra` decimal(15,5) NOT NULL DEFAULT 0.00000 COMMENT 'Minimum order amount for Free Extra',
  `shared` tinyint(10) NOT NULL DEFAULT 1,
  `state` tinyint(3) NOT NULL DEFAULT 0,
  `publish_up` datetime NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'Startdate if nothing is set = permanent',
  `publish_down` datetime NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'Enddate if nothing is set = permanent',
  `locked_on` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `locked_by` int(10) NOT NULL DEFAULT 0,
  `created` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `created_by` int(10) NOT NULL DEFAULT 0,
