CREATE TABLE `dpjvy_standard_orders` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `vendor_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
